#!/usr/bin/env node
// Render the README ranking cards, buttons and ranking table from docs/rankings.json.
//
//   node scripts/readme-badges.mjs            write SVGs under docs/assets/badges and both READMEs
//   node scripts/readme-badges.mjs refresh    re-check GitHub topic ranks and GitHub Trending, then write
//   node scripts/readme-badges.mjs --check    exit 1 when generated files are out of date (used in CI)
//
// Trendshift blocks automated requests, so Trendshift ranks are entered in docs/rankings.json by hand.
// See docs/rankings.md for the update routine.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DATA = 'docs/rankings.json';
const ASSETS = 'docs/assets/badges';
const args = new Set(process.argv.slice(2));
const CHECK = args.has('--check');
const REFRESH = args.has('refresh');

const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei','Noto Sans SC',Helvetica,Arial,sans-serif";
const CARD = {
  light: { bg: '#FFFFFF', stroke: '#4A0E99', disc: '#F1EBFB', rank: '#4A0E99', top: '#6B4FA8', main: '#432787' },
  dark: { bg: '#161B22', stroke: '#8957E5', disc: '#2A1F45', rank: '#D2A8FF', top: '#A38BD8', main: '#E2D4FF' },
};
const BUTTON = {
  primary: {
    light: { bg: '#1F2328', fg: '#FFFFFF', stroke: '#1F2328' },
    dark: { bg: '#F0F6FC', fg: '#0D1117', stroke: '#F0F6FC' },
  },
  secondary: {
    light: { bg: '#FFFFFF', fg: '#1F2328', stroke: '#D1D9E0' },
    dark: { bg: '#212830', fg: '#F0F6FC', stroke: '#3D444D' },
  },
};
const README = {
  zh: {
    file: 'README.md',
    recordsAnchor: '#榜单记录',
    period: { daily: '日榜', weekly: '周榜', monthly: '月榜' },
    all: '全语言',
    head: '| 日期 | 榜单 | 名次 | 说明 |',
    topic: (link) => `GitHub 主题 ${link}`,
    topicNote: (date) => `按累计 Star 排序，核验于 ${date}`,
    snapshot: (s) => `快照 ${s}`,
    footer: '数据来自 [docs/rankings.json](docs/rankings.json)，由 `scripts/readme-badges.mjs` 生成；更新方法见 [榜单维护](docs/rankings.md)。',
    generated: '<!-- 由 scripts/readme-badges.mjs 生成，请修改 docs/rankings.json 后重新运行 -->',
  },
  en: {
    file: 'README.en.md',
    recordsAnchor: '#rankings',
    period: { daily: 'daily', weekly: 'weekly', monthly: 'monthly' },
    all: 'all languages',
    head: '| Date | Ranking | Rank | Notes |',
    topic: (link) => `GitHub topic ${link}`,
    topicNote: (date) => `By total stars, checked ${date}`,
    snapshot: (s) => `Snapshot ${s}`,
    footer: 'Data lives in [docs/rankings.json](docs/rankings.json) and is rendered by `scripts/readme-badges.mjs`. See [ranking maintenance](docs/rankings.md) (Chinese).',
    generated: '<!-- Generated by scripts/readme-badges.mjs. Edit docs/rankings.json and run it again. -->',
  },
};
const BUTTONS = [
  { file: 'cta-try', kind: 'primary', label: '在线体验 →' },
  { file: 'cta-api', kind: 'secondary', label: 'API 快速开始', go: true },
  { file: 'cta-try-en', kind: 'primary', label: 'Try online →' },
  { file: 'cta-api-en', kind: 'secondary', label: 'API Quickstart', go: true },
];
const PERIOD_ORDER = { monthly: 0, weekly: 1, daily: 2 };
const PERIOD_WORD = { daily: 'Day', weekly: 'Week', monthly: 'Month' };
const MAX_TRENDING_ROWS = 10;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const mdCell = (s) => String(s).replace(/\|/g, '\\|');
const topicUrl = (topic) => `https://github.com/topics/${topic}?o=desc&s=stars`;

// Generous advance-width estimate (in em) so text never overflows on narrower system fonts.
function textWidth(text, size, letterSpacing = 0) {
  let em = 0;
  for (const ch of text) {
    if (/[⺀-鿿＀-￯]/.test(ch)) em += 1;
    else if (/[A-Z#@MWmw]/.test(ch)) em += 0.74;
    else if (/[a-z0-9]/.test(ch)) em += 0.6;
    else if (ch === ' ') em += 0.3;
    else em += 0.4;
  }
  return em * size + letterSpacing * [...text].length;
}

function cardSvg({ rank, top, main, title, width }, theme) {
  const c = CARD[theme];
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="55" viewBox="0 0 ${width} 55" role="img" aria-label="${esc(title)}">
  <title>${esc(title)}</title>
  <rect x="0.5" y="0.5" width="${width - 1}" height="54" rx="10" fill="${c.bg}" stroke="${c.stroke}"/>
  <circle cx="31" cy="27.5" r="17" fill="${c.disc}"/>
  <text x="31" y="${rank >= 10 ? 33 : 34}" text-anchor="middle" font-family="${FONT}" font-size="${rank >= 10 ? 15 : 19}" font-weight="700" fill="${c.rank}">${rank}</text>
  <text x="58" y="22" font-family="${FONT}" font-size="9" font-weight="600" letter-spacing="0.8" fill="${c.top}">${esc(top)}</text>
  <text x="58" y="39" font-family="${FONT}" font-size="13.5" font-weight="700" fill="${c.main}">${esc(main)}</text>
</svg>
`;
}

function buttonSvg({ label, kind, go }, theme) {
  const c = BUTTON[kind][theme];
  const logo = go ? 30 : 0;
  const width = Math.ceil(40 + logo + textWidth(label, 14));
  const goMark = go ? `<text x="18" y="25.5" font-family="${FONT}" font-size="14" font-weight="800" font-style="italic" fill="#00ADD8">GO</text>\n  ` : '';
  return {
    width,
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="40" viewBox="0 0 ${width} 40" role="img" aria-label="${esc(go ? `Go ${label}` : label)}">
  <title>${esc(go ? `Go ${label}` : label)}</title>
  <rect x="0.5" y="0.5" width="${width - 1}" height="39" rx="8" fill="${c.bg}" stroke="${c.stroke}"/>
  ${goMark}<text x="${(width + logo) / 2}" y="25.5" text-anchor="middle" font-family="${FONT}" font-size="14" font-weight="600" fill="${c.fg}">${esc(label)}</text>
</svg>
`,
  };
}

function fmtDate(iso) {
  const d = new Date(`${iso}T00:00:00Z`);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).toUpperCase();
}

function pickTrending(list) {
  const pinned = list.find((e) => e.featured);
  if (pinned) return pinned;
  return [...list].sort((a, b) => a.rank - b.rank
    || PERIOD_ORDER[a.period] - PERIOD_ORDER[b.period]
    || (a.scope === 'all' ? 0 : 1) - (b.scope === 'all' ? 0 : 1)
    || b.date.localeCompare(a.date))[0];
}

function trendingCard(entry) {
  if (!entry) return null;
  const word = PERIOD_WORD[entry.period];
  const main = entry.scope === 'all' ? `#${entry.rank} Repository of the ${word}` : `#${entry.rank} ${entry.scope} Repo of the ${word}`;
  const top = `${entry.source === 'trendshift' ? 'TRENDSHIFT' : 'GITHUB TRENDING'} · ${fmtDate(entry.date)}`;
  return { rank: entry.rank, top, main, title: `${top} ${main}`, link: () => entry.url };
}

function topicsCard(topics) {
  const ranked = topics.filter((t) => Number.isInteger(t.rank));
  const firsts = ranked.filter((t) => t.rank === 1);
  if (firsts.length >= 2) {
    return { rank: 1, top: 'GITHUB TOPICS · BY STARS', main: `#1 in ${firsts.length} GitHub Topics`, title: `#1 in ${firsts.length} GitHub topics by stars`, link: (lang) => README[lang].recordsAnchor };
  }
  const best = [...ranked].sort((a, b) => a.rank - b.rank)[0];
  if (!best || best.rank > 3) return null;
  return { rank: best.rank, top: 'GITHUB TOPIC · BY STARS', main: `#${best.rank} ${best.name.en}`, title: `GitHub topic ${best.topic}: #${best.rank} by stars`, link: () => topicUrl(best.topic) };
}

function heroBlock(lang, data, cards) {
  const lines = [README[lang].generated, '<p align="center">'];
  const id = data.trendshift?.repositoryId;
  if (id) {
    lines.push(`  <a href="https://trendshift.io/repositories/${id}"><img src="https://trendshift.io/api/badge/repositories/${id}" alt="${esc(data.repo)} | Trendshift" width="250" height="55" /></a>`);
  }
  for (const c of cards) {
    lines.push(`  <a href="${esc(c.link(lang))}"><picture><source media="(prefers-color-scheme: dark)" srcset="${ASSETS}/${c.file}-dark.svg" /><img src="${ASSETS}/${c.file}.svg" alt="${esc(c.title)}" width="${c.width}" height="55" /></picture></a>`);
  }
  lines.push('</p>');
  return lines.join('\n');
}

function recordsBlock(lang, data) {
  const t = README[lang];
  const rows = [t.generated, '', t.head, '|---|---|---:|---|'];
  const trending = [...data.trending].sort((a, b) => b.date.localeCompare(a.date) || a.rank - b.rank).slice(0, MAX_TRENDING_ROWS);
  for (const e of trending) {
    const source = e.source === 'trendshift' ? 'Trendshift' : 'GitHub Trending';
    const scope = e.scope === 'all' ? t.all : e.scope;
    const board = `${source} ${t.period[e.period]} · ${scope}`;
    rows.push(`| ${e.date} | [${mdCell(board)}](${e.url}) | #${e.rank} | ${e.snapshot ? mdCell(t.snapshot(e.snapshot)) : ''} |`);
  }
  const topics = data.topics.filter((x) => Number.isInteger(x.rank) && x.rank <= 3).sort((a, b) => a.rank - b.rank || a.topic.localeCompare(b.topic));
  for (const x of topics) {
    rows.push(`| ${x.checkedAt} | ${t.topic(`[\`${x.topic}\`](${topicUrl(x.topic)})`)} | #${x.rank} | ${mdCell(t.topicNote(x.checkedAt))} |`);
  }
  rows.push('', t.footer);
  return rows.join('\n');
}

function replaceBlock(text, name, body, file) {
  const start = `<!-- ${name}:start -->`;
  const end = `<!-- ${name}:end -->`;
  const i = text.indexOf(start);
  const j = text.indexOf(end);
  if (i < 0 || j < i) throw new Error(`${file}: missing ${start} … ${end}`);
  return `${text.slice(0, i + start.length)}\n${body}\n${text.slice(j)}`;
}

async function fetchGitHub(url, json) {
  const headers = { 'User-Agent': 'luna-translator-readme-badges', Accept: json ? 'application/vnd.github+json' : 'text/html' };
  if (json && process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  const res = await fetch(url, { headers });
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
  return json ? res.json() : res.text();
}

async function refresh(data) {
  const today = new Date().toISOString().slice(0, 10);
  const repo = await fetchGitHub(`https://api.github.com/repos/${data.repo}`, true);
  for (const topic of repo.topics ?? []) {
    if (!data.topics.some((t) => t.topic === topic)) {
      const title = topic.split('-').map((w) => w[0].toUpperCase() + w.slice(1)).join(' ');
      data.topics.push({ topic, name: { zh: title, en: title }, rank: null, checkedAt: today });
      console.log(`new topic ${topic}: fill in name.zh in ${DATA}`);
    }
  }
  for (const t of data.topics) {
    const q = encodeURIComponent(`topic:${t.topic}`);
    const result = await fetchGitHub(`https://api.github.com/search/repositories?q=${q}&sort=stars&order=desc&per_page=100`, true);
    const i = result.items.findIndex((r) => r.full_name.toLowerCase() === data.repo.toLowerCase());
    const rank = i >= 0 ? i + 1 : null;
    if (rank !== t.rank) console.log(`topic ${t.topic}: ${t.rank ?? '-'} -> ${rank ?? '-'}`);
    t.rank = rank;
    t.checkedAt = today;
  }
  for (const period of ['daily', 'weekly', 'monthly']) {
    for (const scope of ['all', ...(data.trendingLanguages ?? [])]) {
      const url = `https://github.com/trending${scope === 'all' ? '' : `/${scope.toLowerCase()}`}?since=${period}`;
      const html = await fetchGitHub(url, false);
      const names = html.split('<article class="Box-row"').slice(1)
        .map((a) => (a.match(/<h2[^>]*>\s*<a[^>]*href="\/([^"]+)"/) || [])[1]).filter(Boolean);
      if (!names.length) { console.warn(`warning: no repositories parsed from ${url}`); continue; }
      const i = names.findIndex((n) => n.toLowerCase() === data.repo.toLowerCase());
      if (i < 0) continue;
      const entry = { date: today, source: 'github', period, scope, rank: i + 1, url };
      const same = data.trending.find((e) => e.date === today && e.source === 'github' && e.period === period && e.scope === scope);
      if (!same) data.trending.push(entry);
      else if (entry.rank < same.rank) same.rank = entry.rank;
      console.log(`GitHub Trending ${period} ${scope}: #${i + 1}`);
    }
  }
}

async function main() {
  const dataPath = path.join(root, DATA);
  const data = JSON.parse(await readFile(dataPath, 'utf8'));
  if (REFRESH) {
    await refresh(data);
    if (!CHECK) await writeFile(dataPath, `${JSON.stringify(data, null, 2)}\n`);
  }

  const outputs = new Map();
  const cards = [];
  if (!data.trendshift?.repositoryId) {
    const c = trendingCard(pickTrending(data.trending));
    if (c) cards.push({ ...c, file: 'trending' });
  }
  const tc = topicsCard(data.topics);
  if (tc) cards.push({ ...tc, file: 'topics' });
  const width = Math.max(250, ...cards.map((c) => Math.ceil(58 + Math.max(textWidth(c.main, 13.5), textWidth(c.top, 9, 0.8)) + 16)));
  for (const c of cards) {
    c.width = width;
    outputs.set(`${ASSETS}/${c.file}.svg`, cardSvg(c, 'light'));
    outputs.set(`${ASSETS}/${c.file}-dark.svg`, cardSvg(c, 'dark'));
  }
  for (const b of BUTTONS) {
    outputs.set(`${ASSETS}/${b.file}.svg`, buttonSvg(b, 'light').svg);
    outputs.set(`${ASSETS}/${b.file}-dark.svg`, buttonSvg(b, 'dark').svg);
  }
  for (const lang of Object.keys(README)) {
    const file = README[lang].file;
    let text = await readFile(path.join(root, file), 'utf8');
    text = replaceBlock(text, 'rankings:hero', heroBlock(lang, data, cards), file);
    text = replaceBlock(text, 'rankings:records', recordsBlock(lang, data), file);
    outputs.set(file, text);
  }

  const stale = [];
  for (const [rel, content] of outputs) {
    const abs = path.join(root, rel);
    const current = await readFile(abs, 'utf8').catch(() => null);
    if (current === content) continue;
    stale.push(rel);
    if (!CHECK) {
      await mkdir(path.dirname(abs), { recursive: true });
      await writeFile(abs, content);
    }
  }
  if (CHECK && stale.length) {
    console.error(`Out of date: ${stale.join(', ')}\nRun: node scripts/readme-badges.mjs`);
    process.exit(1);
  }
  console.log(stale.length ? `Updated ${stale.join(', ')}` : 'README rankings are up to date');
}

main().catch((err) => { console.error(err.message); process.exit(1); });
